/* ==== fftchode numerics switch (FFTE-6) ====
 * mode 0 = baseline: bit-identical to baseline-v0 (outputs and wisdom).
 * mode 1 = fast: changes that may alter floating-point results (here: SIMD codelets).
 * FFTCHODE_NUMERICS=baseline|fast is read once, at first use, unless
 * fftchode_set_numerics() was called before.  Each mode has its own planner and
 * wisdom; plans made in one mode stay valid after a switch.  Switch modes between
 * planner calls, not concurrently with planning in another thread. */
#include <algorithm>
#include <atomic>
#include <cctype>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
static std::atomic<int> fftchode_numerics_{-1};
extern "C" void fftchode_set_numerics(int mode)
{
     fftchode_numerics_.store(mode == 1 ? 1 : 0);
}
extern "C" int fftchode_numerics_mode(void)
{
     int m = fftchode_numerics_.load(std::memory_order_relaxed);
     if (m < 0) {
          const char *e = std::getenv("FFTCHODE_NUMERICS");
          int unset = -1;
          fftchode_numerics_.compare_exchange_strong(unset, e && (!std::strcmp(e, "fast") || !std::strcmp(e, "1")));
          m = fftchode_numerics_.load(std::memory_order_relaxed);
     }
     return m;
}

/* SIMD codelets: compiled for every x86-64 and aarch64 target with GCC-compatible
   compilers, registered with the planner only in fast mode and only when the CPU
   supports them (FFTW's cpuid/xgetbv checks). */
#if !defined(FFT_NO_SIMD) && defined(__GNUC__) && defined(__x86_64__)
#define FFTCHODE_SIMD_X86 1
#include <immintrin.h>
#elif !defined(FFT_NO_SIMD) && defined(__GNUC__) && defined(__aarch64__)
#define FFTCHODE_SIMD_NEON 1
#include <arm_neon.h>
#endif
/* fast mode adds fftchode's own solvers (rdft2-pair, rdft2-embed, dft-colpack) to FFTW's; FFTCHODE_FAST_SOLVERS=upstream
   leaves them out, so that fast mode equals upstream FFTW with the same SIMD extensions */
static int fftchode_extra_solvers(void)
{
     const char *e = std::getenv("FFTCHODE_FAST_SOLVERS");
     return fftchode_numerics_mode() == 1 && !(e && !std::strcmp(e, "upstream"));
}
#if defined(FFTCHODE_SIMD_X86) || defined(FFTCHODE_SIMD_NEON)
/* FFTCHODE_SIMD=<comma-separated list> limits the extensions fast mode registers */
static int fftchode_simd_allowed(const char *isa)
{
     if (fftchode_numerics_mode() != 1)
          return 0;
     const char *e = std::getenv("FFTCHODE_SIMD");
     if (!e || !*e)
          return 1;
     size_t n = std::strlen(isa);
     for (const char *p = e;;) {
          const char *q = std::strchr(p, ',');
          size_t len = q ? (size_t)(q - p) : std::strlen(p);
          if (len == n && !std::strncmp(p, isa, n))
               return 1;
          if (!q)
               return 0;
          p = q + 1;
     }
}
#endif


/* ==== fftchode: runtime ISA multiversioning of the scalar codelets ==== */
/* Each codelet is compiled three times from the same source text: generic (the build's flags),
   AVX2, and AVX-512 (per-function target attributes).  The copies execute the same IEEE
   operations in the same order; only instruction encoding, register allocation and scheduling
   differ, so results are bit-identical.  FP contraction stays off (the build passes
   -ffp-contract=off; clang additionally gets the pragma below).  The copy is chosen when a
   planner registers its codelets: the best ISA the CPU and OS support, capped by the
   environment variable FFTCHODE_ISA=generic|avx2|avx512 (read once).  Define FFTCHODE_NO_MV to
   compile only the generic copy. */
#if !defined(FFTCHODE_NO_MV) && defined(__x86_64__) && (defined(__clang__) || (defined(__GNUC__) && __GNUC__ >= 8))
#define FFTCHODE_MV 1
#ifdef __clang__
#pragma STDC FP_CONTRACT OFF
#endif
#ifdef __clang__
#define FFTCHODE_TARGET_AVX2 __attribute__((target("avx2")))
#define FFTCHODE_TARGET_AVX512 __attribute__((target("avx512f,avx512vl,avx512bw,avx512dq")))
#else
/* GCC ignores the STDC FP_CONTRACT pragma and contracts by default in GNU modes; avx512f
   enables FMA, so keep contraction off in the copies whatever the build flags are. */
#define FFTCHODE_TARGET_AVX2 __attribute__((target("avx2"), optimize("fp-contract=off")))
#define FFTCHODE_TARGET_AVX512 __attribute__((target("avx512f,avx512vl,avx512bw,avx512dq"), optimize("fp-contract=off")))
#endif
#include <stdlib.h>
#include <string.h>
static int fftchode_isa_level(void)
{
     static const int level = [] {
          int hw = 0;
          __builtin_cpu_init();
          if (__builtin_cpu_supports("avx2")) hw = 1;
          if (hw && __builtin_cpu_supports("avx512f") && __builtin_cpu_supports("avx512vl")
              && __builtin_cpu_supports("avx512bw") && __builtin_cpu_supports("avx512dq")) hw = 2;
          const char *e = getenv("FFTCHODE_ISA");
          int cap = 2;
          if (e && !strcmp(e, "generic")) cap = 0;
          else if (e && !strcmp(e, "avx2")) cap = 1;
          return hw < cap ? hw : cap;
     }();
     return level;
}
/* desc -> generic copy, filled at registration, for the plan-time fallback below */
static struct { const void *desc; void (*generic)(void); } fftchode_mv_tab[4096];
static void fftchode_mv_note(const void *desc, void (*generic)(void))
{
     unsigned h = (unsigned)(((unsigned long)desc >> 4) * 2654435761u) & 4095u;
     while (fftchode_mv_tab[h].desc && fftchode_mv_tab[h].desc != desc) h = (h + 1) & 4095u;
     fftchode_mv_tab[h].generic = generic;
     fftchode_mv_tab[h].desc = desc;
}
static void (*fftchode_mv_generic(const void *desc))(void)
{
     unsigned h = (unsigned)(((unsigned long)desc >> 4) * 2654435761u) & 4095u;
     while (fftchode_mv_tab[h].desc && fftchode_mv_tab[h].desc != desc) h = (h + 1) & 4095u;
     return fftchode_mv_tab[h].generic;
}
/* The AVX-512 copies keep more loads in flight (32 registers, fewer spills).  When a codelet's
   rows fall on few L1 sets (large power-of-two strides: many rows map to the same set of a
   64-set, 64-byte-line L1) that turns into extra conflict misses, so such plans use the
   generic copy: rows / (distinct sets) >= 8 (FFTCHODE_MV_CONFLICT=<n> overrides, 0 disables).
   This only selects which of the bit-identical copies runs. */
static int fftchode_conflict(long n, long sbytes)
{
     static const int thr = [] { const char *e = getenv("FFTCHODE_MV_CONFLICT"); return e ? atoi(e) : 8; }();
     if (thr <= 0 || fftchode_isa_level() < 2) return 0;
     unsigned long long sets = 0;
     for (long k = 0; k < n; k++) sets |= 1ull << (((unsigned long)(k * sbytes) >> 6) & 63);
     long d = __builtin_popcountll(sets);
     return (n + d - 1) / d >= thr;
}
#define FFTCHODE_PICK(f, desc) (fftchode_mv_note((desc), (void (*)(void))(f)), fftchode_isa_level() == 2 ? f##_avx512 : fftchode_isa_level() == 1 ? f##_avx2 : f)
#define FFTCHODE_STRIDE_FALLBACK(k, desc, n, s1, s2)                                  \
     do {                                                                         \
          if (fftchode_conflict((n), (long)(s1) * (long)sizeof(R))               \
              || fftchode_conflict((n), (long)(s2) * (long)sizeof(R))) {         \
               void (*g_)(void) = fftchode_mv_generic(desc);                      \
               if (g_) (k) = (decltype(k))g_;                                     \
          }                                                                       \
     } while (0)
#else
#define FFTCHODE_MV 0
#define FFTCHODE_PICK(f, desc) (f)
#define FFTCHODE_STRIDE_FALLBACK(k, desc, n, s1, s2) ((void)0)
#endif

#define FFTCHODE_FCW_INIT { 1,1.397,1.802,2.308,4.549,0,39.11,0.9886,0,0.9091,1.066,0,0,0.8838,0.9278,0.9154,1.016,0.5812,0.7173,0.155,1.345,1.456,1.145,0.8925,0.5188,0.9154,0,1.36,8.137,9.919,0.9093,0.07543,1.262,8.516,11.2,0.0975 }
/* ==== fftchode fast-mode ESTIMATE planner (opt/planner, FFTE-6) ====
 * In fast mode FFTW_ESTIMATE searches every applicable plan (no pruning) and
 * ranks them with a cost that adds a memory-traffic and codelet-efficiency
 * model to FFTW's operation count (see X(fc_mem), X(fc_loop), X(fc_arith)).
 * The weights were fitted offline on this CPU class (bench/planner/calibrate.sh)
 * on problem sizes outside the frozen suite.  Index: 0 arithmetic outside
 * codelets, 1 FFTW's "other" ops (copies), 2-5 cache lines fetched from
 * L1/L2/L3/DRAM, 6 child-plan calls in loops, 7-34 codelet arithmetic by
 * register width (scalar, 128, 256, 512 bits) x family (n1 n2 t1 t2 t3 q1
 * real), 35 extra for codelets of radix > 16.
 * A threaded plan (X(fc_thr)) costs its parallel part divided by the lanes
 * the thread pool will actually run it on (the CPUs in the process's affinity
 * mask, fewer when the work is too small to wake a thread), plus
 * FFTCHODE_FC_SPAWN cost units per parallel region (one unit is ~0.13 ns on
 * the calibration machine).
 * The unpruned search evaluates at most FFTCHODE_PLAN_BUDGET plans per
 * top-level plan; after that it prunes as stock ESTIMATE does.  The budget is
 * a count, not a time, so plans stay reproducible.
 * Building with -DFFTCHODE_PLANNER_CALIBRATE reads FFTCHODE_PLANW (36
 * comma-separated weights), FFTCHODE_PLANSPAWN (spawn cost),
 * FFTCHODE_PLANBUDGET (plan budget) and FFTCHODE_PLANRAND (sigma,seed: random
 * cost perturbation for sampling plans). */
#include <thread>
#define FFTCHODE_FC_SPAWN 1.2e5
#define FFTCHODE_PLAN_BUDGET 10000
static const double fftchode_fcw_default[36] = FFTCHODE_FCW_INIT;
#ifdef FFTCHODE_PLANNER_CALIBRATE
#include <cmath>
static double fftchode_fcw_[36];
static double fftchode_rand_[2];
static int fftchode_fcw_init_ = 0;
static void fftchode_fcw_load(void)
{
     const char *e = std::getenv("FFTCHODE_PLANW"), *r = std::getenv("FFTCHODE_PLANRAND");
     int i;
     for (i = 0; i < 36; ++i) fftchode_fcw_[i] = fftchode_fcw_default[i];
     for (i = 0; e && *e && i < 36; ++i) {
          char *q; double x = std::strtod(e, &q);
          if (q == e) break;
          fftchode_fcw_[i] = x; e = (*q == ',') ? q + 1 : q;
     }
     for (i = 0; r && *r && i < 2; ++i) {
          char *q; double x = std::strtod(r, &q);
          if (q == r) break;
          fftchode_rand_[i] = x; r = (*q == ',') ? q + 1 : q;
     }
     fftchode_fcw_init_ = 1;
}
static const double *fftchode_fcw(void)
{
     if (!fftchode_fcw_init_) fftchode_fcw_load();
     return fftchode_fcw_;
}
static double fftchode_fc_spawn(void)
{
     const char *e = std::getenv("FFTCHODE_PLANSPAWN");
     return e ? std::atof(e) : FFTCHODE_FC_SPAWN;
}
static int fftchode_plan_budget(void)
{
     const char *e = std::getenv("FFTCHODE_PLANBUDGET");
     return e ? std::atoi(e) : FFTCHODE_PLAN_BUDGET;
}
#else
static const double *fftchode_fcw(void) { return fftchode_fcw_default; }
static double fftchode_fc_spawn(void) { return FFTCHODE_FC_SPAWN; }
static int fftchode_plan_budget(void) { return FFTCHODE_PLAN_BUDGET; }
#endif

