/*-----------------------------------------------------------------------*/
/* ops.c: */
/*
 * ops counter.  The total number of additions is add + fma
 * and the total number of multiplications is mul + fma.
 * Total flops = add + mul + 2 * fma
 */
typedef struct {
     double add;
     double mul;
     double fma;
     double other;
     /* fftchode fast mode: [0-3] cache lines fetched from L1, L2, L3, DRAM;
        [4] child-plan calls in loops; [5-32] codelet arithmetic by register
        width (scalar, 128, 256, 512 bits) x family (n1 n2 t1 t2 t3 q1 real);
        [33] arithmetic of codelets with radix > 16; [34] cost-unit adjustment
        for threaded plans (X(fc_thr)) */
     double fcl[35];
} opcnt;

extern "C" void X(ops_zero)(opcnt *dst);
extern "C" void X(ops_other)(INT o, opcnt *dst);
extern "C" void X(ops_cpy)(const opcnt *src, opcnt *dst);

extern "C" void X(ops_add)(const opcnt *a, const opcnt *b, opcnt *dst);
extern "C" void X(ops_add2)(const opcnt *a, opcnt *dst);

/* dst = m * a + b */
extern "C" void X(ops_madd)(INT m, const opcnt *a, const opcnt *b, opcnt *dst);

/* dst += m * a */
extern "C" void X(ops_madd2)(INT m, const opcnt *a, opcnt *dst);


