/****************************************************************************/
/* problem2.c: */
/* 
   An RDFT2 problem transforms a 1d real array r[n] with stride is/os
   to/from an "unpacked" complex array {rio,iio}[n/2 + 1] with stride
   os/is.  R0 points to the first even element of the real array.  
   R1 points to the first odd element of the real array.

   Strides on the real side of the transform express distances
   between consecutive elements of the same array (even or odd).
   E.g., for a contiguous input

     R0 R1 R2 R3 ...

   the input stride would be 2, not 1.  This convention is necessary
   for hc2c codelets to work, since they transpose even/odd with
   real/imag.
   
   Multidimensional transforms use complex DFTs for the
   noncontiguous dimensions.  vecsz has the usual interpretation.  
*/
typedef struct {
     problem super;
     tensor *sz;
     tensor *vecsz;
     R *r0, *r1;
     R *cr, *ci;
     rdft_kind kind; /* assert(kind < DHT) */
} problem_rdft2;

extern "C" problem *X(mkproblem_rdft2)(const tensor *sz, const tensor *vecsz,
			    R *r0, R *r1, R *cr, R *ci, rdft_kind kind);
extern "C" problem *X(mkproblem_rdft2_d)(tensor *sz, tensor *vecsz,
			      R *r0, R *r1, R *cr, R *ci, rdft_kind kind);
extern "C" problem *X(mkproblem_rdft2_d_3pointers)(tensor *sz, tensor *vecsz,
					R *r, R *cr, R *ci, rdft_kind kind);
extern "C" int X(rdft2_inplace_strides)(const problem_rdft2 *p, int vdim);
extern "C" INT X(rdft2_tensor_max_index)(const tensor *sz, rdft_kind k);
extern "C" void X(rdft2_strides)(rdft_kind kind, const iodim *d, INT *rs, INT *cs);
extern "C" INT X(rdft2_complex_n)(INT real_n, rdft_kind kind);

/* verify.c: */
extern "C" void X(rdft2_verify)(plan *pln, const problem_rdft2 *p, int rounds);

/* solve.c: */
extern "C" void X(rdft2_solve)(const plan *ego_, const problem *p_);

/* plan.c: */
typedef void (*rdft2apply) (const plan *ego, R *r0, R *r1, R *cr, R *ci);

typedef struct {
     plan super;
     rdft2apply apply;
} plan_rdft2;

extern "C" plan *X(mkplan_rdft2)(size_t size, const plan_adt *adt, rdft2apply apply);

#define MKPLAN_RDFT2(type, adt, apply) \
  (type *)X(mkplan_rdft2)(sizeof(type), adt, apply)

/* various solvers */

extern "C" solver *X(mksolver_rdft2_direct)(kr2c k, const kr2c_desc *desc);

extern "C" void X(rdft2_vrank_geq1_register)(planner *p);
extern "C" void X(rdft2_buffered_register)(planner *p);
extern "C" void X(rdft2_rdft_register)(planner *p);
extern "C" void X(rdft2_nop_register)(planner *p);
extern "C" void X(rdft2_rank0_register)(planner *p);
extern "C" void X(rdft2_rank_geq2_register)(planner *p);

